import{_ as e,o as d,c as r,a2 as o}from"./chunks/framework.uw_ZoRon.js";const m=JSON.parse('{"title":"Glossary — Erlang/Elixir ↔ RUSM","description":"","frontmatter":{},"headers":[],"relativePath":"deep-dive/glossary.md","filePath":"deep-dive/glossary.md"}'),s={name:"deep-dive/glossary.md"};function a(i,t,n,c,l,h){return d(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="glossary-—-erlang-elixir-↔-rusm" tabindex="-1">Glossary — Erlang/Elixir ↔ RUSM <a class="header-anchor" href="#glossary-—-erlang-elixir-↔-rusm" aria-label="Permalink to &quot;Glossary — Erlang/Elixir ↔ RUSM&quot;">​</a></h1><p>Coming from the BEAM? RUSM&#39;s model is deliberately familiar. This table maps the Erlang/Elixir concepts you already know onto their RUSM equivalents.</p><table tabindex="0"><thead><tr><th>Erlang/Elixir</th><th>RUSM</th><th>Notes</th></tr></thead><tbody><tr><td>process</td><td>a Wasm instance running as a Tokio task</td><td>own stack, heap, syscalls, permissions</td></tr><tr><td>scheduler</td><td>a Tokio worker thread (work-stealing)</td><td>M:N over a few OS threads</td></tr><tr><td>reduction counting</td><td>Wasmtime epoch interruption</td><td>forces fair yields, even in tight loops</td></tr><tr><td>mailbox</td><td>per-process async channel</td><td>host copies message bytes across memories</td></tr><tr><td><code>send/2</code></td><td><code>send(pid, msg)</code></td><td>fire-and-forget to a mailbox (<code>Process.send</code> / <code>send_bytes</code> / <code>Send</code>)</td></tr><tr><td><code>receive</code></td><td><code>receive()</code></td><td>suspends the process until a message arrives (<code>Process.receive</code> / <code>receive_bytes</code> / <code>Receive</code>)</td></tr><tr><td>link</td><td>bidirectional failure propagation (OTP core)</td><td>a crash signals linked peers; guests use <code>monitor</code> + an in-guest <code>Supervisor</code></td></tr><tr><td>monitor</td><td>one-way failure notification</td><td>observe without dying together; a <code>__down</code> message, no polling</td></tr><tr><td>supervisor</td><td>a process that restarts crashing children</td><td>&quot;let it crash&quot;</td></tr><tr><td><code>:global</code></td><td>distributed registry</td><td>cluster-wide name → pid</td></tr><tr><td><code>Node.connect/1</code>, epmd</td><td>QUIC + TLS node transport</td><td>secure node-to-node links</td></tr><tr><td><code>iex --remsh</code></td><td><code>rusm attach &lt;node&gt;</code></td><td>live REPL into a running node</td></tr><tr><td><code>:observer</code></td><td>the dashboard&#39;s observer view</td><td>live processes, schedulers, memory</td></tr><tr><td>BEAM</td><td>the RUSM runtime (Rust + Tokio + Wasmtime)</td><td>the host that runs everything</td></tr></tbody></table><p>Dashboard &amp; benchmark terms — the wire between a node and the observer/REPL:</p><table tabindex="0"><thead><tr><th>Term</th><th>Meaning</th></tr></thead><tbody><tr><td>frame</td><td>one sampled tick (throughput, latency, observer snapshot) sent to clients</td></tr><tr><td>scenario</td><td>a named benchmark (e.g. <code>connection-storm</code>) the node runs and streams; all scenarios now run on real engines</td></tr><tr><td>synthetic source</td><td>a deterministic generator producing scenario-shaped data per tick — the Phase-0 bootstrap, before the engines were real</td></tr><tr><td>detail toggle</td><td>switch for the costly per-instance observer table</td></tr></tbody></table>',5)])])}const g=e(s,[["render",a]]);export{m as __pageData,g as default};
